
const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const helpTopics=[
 {group:'Everyday routines',topics:['After-school routines','Morning routines','Bedtime transitions','Mealtimes','Leaving the house','Transitions between activities']},
 {group:'Screens and play',topics:['Screen-time alternatives','Turning screens off','Handling boredom','Independent play','Creative and outdoor play']},
 {group:'Connection and emotions',topics:['Connection and quality time','Big feelings and frustration','Calming down','Social skills and friendships','Sibling relationships']},
 {group:'Family life',topics:['Boundaries and cooperation','Consistency across caregivers','Learning and homework routines','Caregiver capacity and schedules','Something else']}
];
let nextChildId=0;
function newChild(){return {id:'child-'+Date.now().toString(36)+'-'+(++nextChildId),name:'',age:'5',goals:[],otherGoal:'',needs:'',helps:''}}
function migrateFamily(old){
 if(Array.isArray(old?.children)&&old.children.length){return {...old,children:old.children.map(c=>({...newChild(),...c,goals:Array.isArray(c.goals)?c.goals:[]}))}}
 const child={...newChild(),age:old?.age||'5',goals:old?.goal?[old.goal]:[],needs:old?.needs||'',helps:old?.helps||''};
 return {name:'',children:[child],activeChildId:child.id};
}
const initial={family:migrateFamily(null),saved:[],feedback:[],filters:['At home','Low energy','10 minutes'],concern:'',started:false};
let data;try{data={...structuredClone(initial),...JSON.parse(localStorage.getItem('paal-prototype')||'{}')}}catch{data=structuredClone(initial)}
data.family=migrateFamily(data.family);
let familyDraft=structuredClone(data.family);
let page='family',lastPage='options',selected=null,feedbackChoice='',tab='saved',query='',offset=0,resourceCategory='All';
function activeChild(){return data.family.children.find(c=>c.id===data.family.activeChildId)||data.family.children[0]}
function childLabel(c,i){return c.name.trim()||'Child '+(i+1)}
function collectFamily(formData){return {...familyDraft,name:String(formData.get('family-name')||'').trim(),children:familyDraft.children.map(c=>({...c,name:String(formData.get('name-'+c.id)||'').trim(),age:String(formData.get('age-'+c.id)||'5'),goals:formData.getAll('goals-'+c.id).map(String),otherGoal:String(formData.get('other-'+c.id)||'').trim(),needs:String(formData.get('needs-'+c.id)||'').trim(),helps:String(formData.get('helps-'+c.id)||'').trim()}))}}
function familyErrors(family){let errors=[];family.children.forEach((c,i)=>{const label=childLabel(c,i);if(!c.goals.length)errors.push(label+': choose at least one area for support.');if(c.goals.includes('Something else')&&!c.otherGoal)errors.push(label+': describe the other area you want help with.');if(!c.needs.trim())errors.push(label+': add needs and preferences, or write “No specific needs”.')});return errors}
function familyMarkup(){return `<div class="split"><section><div class="eyebrow">Your family unit</div><h1>About your family.</h1><p class="muted">Add each child and tell us what would make support useful. You can update your family anytime.</p><form id="family-form"><label class="field"><span>Family name <span class="muted">(optional)</span></span><input name="family-name" value="${esc(familyDraft.name||'')}" placeholder="A name for your family unit" autocomplete="off" maxlength="80"></label><div id="family-errors" class="error" role="alert" tabindex="-1"></div>${familyDraft.children.map((c,i)=>`<fieldset class="child-section"><legend>${esc(childLabel(c,i))}</legend><div class="child-header"><span class="muted">Child ${i+1} of ${familyDraft.children.length}</span>${familyDraft.children.length>1?`<button class="remove-child" type="button" data-remove-child="${c.id}" aria-label="Remove ${esc(childLabel(c,i))}">Remove child</button>`:''}</div><div class="inline-grid"><label class="field"><span>Nickname <span class="muted">(optional)</span></span><input name="name-${c.id}" value="${esc(c.name)}" placeholder="e.g. Alex" autocomplete="off" maxlength="60"></label><label class="field"><span>Age <span aria-hidden="true">*</span></span><select name="age-${c.id}" required>${Array.from({length:11},(_,n)=>n+2).map(a=>`<option ${String(a)===String(c.age)?'selected':''} value="${a}">${a} years</option>`).join('')}</select></label></div><div class="field"><span id="goals-label-${c.id}">What do you need help with? <span aria-hidden="true">*</span></span><p class="muted">Choose all that apply.</p><div class="topic-groups" role="group" aria-labelledby="goals-label-${c.id}">${helpTopics.map(g=>`<div class="topic-group"><h3>${g.group}</h3><div class="topic-grid">${g.topics.map(t=>`<label class="topic-choice"><input type="checkbox" name="goals-${c.id}" value="${esc(t)}" ${c.goals.includes(t)?'checked':''}><span>${t}</span></label>`).join('')}</div></div>`).join('')}</div></div><label class="field" id="other-field-${c.id}" ${c.goals.includes('Something else')?'':'hidden'}><span>What else would you like help with? *</span><input name="other-${c.id}" value="${esc(c.otherGoal)}" ${c.goals.includes('Something else')?'required':''} placeholder="Describe the area you have in mind" maxlength="300"></label><label class="field"><span>Needs and preferences <span aria-hidden="true">*</span></span><textarea name="needs-${c.id}" required aria-describedby="needs-hint-${c.id}" placeholder="Interests, sensory or accessibility needs, routines, available time or space…">${esc(c.needs)}</textarea><small class="muted" id="needs-hint-${c.id}">What should options take into account? If none, write “No specific needs”.</small></label><label class="field"><span>What already helps? <span class="muted">(optional)</span></span><input name="helps-${c.id}" value="${esc(c.helps)}" placeholder="Activities or approaches that work for this child" maxlength="300"></label></fieldset>`).join('')}<button class="add-child" type="button" id="add-child">+ Add another child</button><div class="actions"><button class="primary" type="submit">Save family unit <span>→</span></button></div><p class="muted">* Required for each child.</p></form><div class="notice">This demo saves your family unit in this browser, without an account. Use fictional details while exploring.</div></section><aside class="panel lav family-aside"><div class="small-art">${art()}</div><h2>One family. Different needs.</h2><p class="muted">Keep each child’s preferences together, then choose who you’re finding options for.</p><p class="muted">${familyDraft.children.length} ${familyDraft.children.length===1?'child':'children'} in your family unit</p></aside></div>`}
function childSelector(){return `<label class="child-picker"><span>Finding options for</span><select id="active-child" aria-label="Choose a child">${data.family.children.map((c,i)=>`<option value="${c.id}" ${c.id===activeChild().id?'selected':''}>${esc(childLabel(c,i))} · age ${esc(c.age)}</option>`).join('')}</select></label><button type="button" class="link" data-go="family">Edit family</button>`}
function persist(){try{localStorage.setItem('paal-prototype',JSON.stringify(data))}catch{toast('Browser storage is unavailable. Changes last for this visit.')}}
function toast(t){$('#announcer').innerHTML='<div class="toast">'+esc(t)+'</div>';setTimeout(()=>$('#announcer').innerHTML='',3000)}
const icons={today:'⌂',toolkit:'♧',family:'♙'};
function art(kind='pair'){return `<svg viewBox="0 0 440 330" role="img" aria-label="A friendly lavender character and peach companion"><path d="M5 315Q40 150 110 270Q130 290 185 315" fill="#c6b477"/><path d="M100 297C96 236 119 179 148 133C166 104 192 66 221 74C257 82 251 114 227 147C198 187 191 244 192 296Z" fill="#cfb7ef"/><path d="M273 296C269 270 259 249 265 214C272 169 328 172 337 212C345 249 354 277 346 297Z" fill="#ffd0b3"/><g fill="white"><ellipse cx="220" cy="103" rx="10" ry="13"/><ellipse cx="240" cy="112" rx="10" ry="13"/><ellipse cx="293" cy="207" rx="9" ry="12"/><ellipse cx="314" cy="206" rx="9" ry="12"/></g><g fill="#20251f"><circle cx="224" cy="108" r="5"/><circle cx="241" cy="117" r="5"/><circle cx="291" cy="210" r="4"/><circle cx="312" cy="210" r="4"/></g><g fill="none" stroke="#20251f" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M165 156Q146 250 253 217L271 205M181 160Q178 219 247 207M282 246Q265 231 254 218M327 243Q347 234 354 219M112 286L98 308L127 308M182 286L192 307L212 309M283 287L275 307L257 307M331 286L340 306L355 306M205 146L214 149"/><path d="M250 210L270 175"/><path d="M66 183L60 172M76 178L74 166M363 176L371 163M372 183L385 176"/></g><g fill="#c6b477" stroke="#20251f" stroke-width="1.5"><ellipse cx="270" cy="169" rx="7" ry="14"/><ellipse cx="270" cy="169" rx="14" ry="6"/><circle cx="270" cy="169" r="4"/></g><path d="M207 311L211 287Q218 276 235 286L246 275L249 294L241 305L241 319L234 319L232 306L220 306L218 319L212 319" fill="#155640" stroke="#20251f" stroke-width="2"/><circle cx="243" cy="285" r="2"/><path d="M210 293Q194 288 199 278" fill="none" stroke="#155640" stroke-width="4"/></svg>`}
const ideas=[
{id:'connect',title:'Connect, then choose',desc:'A short check-in, then two simple choices.',time:'5 min',supplies:'No supplies',tags:['screen','routine','transition','after','upset','tantrum'],steps:['Start with a brief, calm check-in.','Offer two options you are comfortable with, such as drawing or a quiet game.','Let your child choose the first step.'],quote:'Would you like to draw together or pick a quiet game?',fallback:'If neither option fits, pause and ask what feels hard. You can simplify the choices or revisit the moment later.'},
{id:'draw',title:'Draw the day',desc:'Share a moment from the day on paper.',time:'10 min',supplies:'Paper + crayons',tags:['after','school','connect','bored','screen','video'],steps:['Set out paper and whatever drawing tools you already have.','Invite your child to draw one moment from their day.','Ask about the drawing without needing it to look a particular way.'],quote:'Want to draw something funny, tricky, or interesting from today?',fallback:'Try drawing alongside your child, or let them tell you a story instead. It is fine if drawing is not their preference.'},
{id:'routine',title:'Make a transition plan',desc:'Choose a familiar first step together.',time:'5 min',supplies:'No supplies',tags:['bed','sleep','routine','transition','after','leave'],steps:['Choose a calm moment to talk about the transition.','Agree on one small first step, such as putting down bags or choosing a book.','Try the same starting step next time and adjust together.'],quote:'What could we do first when we get home to make it feel easier?',fallback:'Make the first step smaller or offer a choice between two starting points. Treat this as an experiment rather than a rule you must perfect.'},
{id:'story',title:'Make up a tiny story',desc:'Take turns adding one sentence.',time:'5 min',supplies:'No supplies',tags:['bored','wait','car','connect','screen'],steps:['Start with a character and a funny place.','Invite your child to add a word, sound, or sentence.','Take turns and let the story end whenever you like.'],quote:'A tiny dog found a giant shoe. What happened next?',fallback:'Offer two silly possibilities or tell the first few lines yourself. No need to correct or finish the story.'},
{id:'notice',title:'A noticing walk',desc:'Explore a familiar space together.',time:'10 min',supplies:'No supplies',tags:['outside','energy','bored','screen'],steps:['Choose a safe place you can explore together.','Invite your child to notice a color, shape, or sound.','Follow one thing they are curious about.'],quote:'Can we find something tiny, something round, and something that moves?',fallback:'Stay indoors and look from a window or explore a room. Adjust to your child’s mobility and sensory needs.'},
{id:'book',title:'Choose a quiet book moment',desc:'Look, talk, or make up your own version.',time:'5 min',supplies:'A familiar book',tags:['bed','sleep','quiet','tired','screen'],steps:['Offer a familiar book in a comfortable spot.','Let your child choose a page or picture.','Read, describe pictures, or invent your own story together.'],quote:'Which page should we explore first?',fallback:'Try a shorter moment or a different format. Looking at one picture together can be enough for now.'}
];
function options(){let terms=(data.concern+' '+activeChild().goals.join(' ')+' '+activeChild().otherGoal).toLowerCase();return [...ideas].sort((a,b)=>score(b,terms)-score(a,terms))}function score(x,t){return x.tags.reduce((n,w)=>n+(t.includes(w)?2:0),0)+(data.filters.includes('No extra supplies')&&x.supplies==='No supplies'?4:0)+(data.filters.includes('Low energy')&&x.id==='notice'?-3:0)+(data.filters.includes('5 minutes')&&x.time==='5 min'?3:0)}
function navigate(p){if(p==='family'&&page!=='family')familyDraft=structuredClone(data.family);page=p;query='';render();window.scrollTo({top:0,behavior:'instant'})}function selectIdea(id,from){selected=ideas.find(x=>x.id===id);lastPage=from||page;navigate('detail')}function saveIdea(id){if(data.saved.includes(id)){data.saved=data.saved.filter(x=>x!==id);toast('Removed from your toolkit')}else{data.saved.push(id);toast('Saved to your toolkit')}persist();render()}
function nav(mobile=false){return `<nav class="${mobile?'mobile-nav':'side-nav'}" aria-label="Main navigation">${['today','toolkit','family'].map(n=>`<button class="${mobile?'':'nav-item '}${(page===n||(n==='today'&&['options','detail','feedback','circumstances'].includes(page))||(n==='toolkit'&&page==='resources'))?'active':''}" data-go="${n}"><span aria-hidden="true">${icons[n]}</span>${n[0].toUpperCase()+n.slice(1)}</button>`).join('')}</nav>`}
function shell(content){$('#app').innerHTML=`<div class="layout ${page==='welcome'?'welcome-page':''}"><aside class="sidebar"><button class="logo" data-go="welcome" aria-label="Paal welcome">paal</button>${nav()}<div class="side-foot"><span class="prototype">Interactive prototype</span><p>A few more possibilities.<br>A little more confidence.</p><button class="reset" id="reset">Reset demo</button></div></aside><main class="main"><header class="topbar"><button class="logo" data-go="welcome">paal</button><span class="tagline">Your family. Your way.</span><button class="profile" data-go="family" aria-label="Family profile">♙</button></header><div class="fade">${content}</div></main>${nav(true)}</div>`;bind()}
function render(){let content='';if(page==='welcome')content=`<div class="hero"><div><div class="eyebrow">A companion for everyday parenting</div><h1>More ways to handle everyday parenting.</h1><p class="lead">Options and resources that fit your family, your circumstances, and the moment you're in.</p><div class="actions"><button class="primary" data-go="family">Get started <span>↗</span></button><button class="link" id="explore">Explore the demo</button></div></div><div class="art">${art()}</div></div><div class="welcome-foot"><span>Tailored to your circumstances</span><span>Practical options</span><span>Room to try again</span></div><p class="muted">An interactive concept with sample suggestions. No account needed.</p>`;
if(page==='family')content=familyMarkup();
if(page==='today')content=`<div class="split"><section><div class="eyebrow">Today</div><h1>What's happening today?</h1><p class="muted">Start with a moment you’d like another way to handle.</p><form id="ask-form"><label for="concern" class="badge">Tell us what's happening</label><textarea class="concern" id="concern" name="concern" placeholder="My child asks for videos after school. What else could we try?">${esc(data.concern)}</textarea><div class="section"><span class="muted">Right now</span><div class="chips">${data.filters.map(f=>`<span class="chip">${esc(f)}</span>`).join('')}<button class="link" type="button" data-go="circumstances">Adjust</button></div>${childSelector()}</div><button class="primary" type="submit">Find options <span>→</span></button><p class="muted">Or try: <button class="link example" type="button">Bedtime is always a struggle</button></p></form></section><aside><div class="panel lav"><div class="small-art">${art()}</div><h2>A few more possibilities.</h2><p class="muted">You don't need the perfect words. Tell us what’s going on.</p></div>${data.saved.length?`<button class="row" onclick="selectIdea('${data.saved[0]}','today')"><span class="grow"><span class="muted">Pick up where you left off</span><h3>${esc(ideas.find(x=>x.id===data.saved[0])?.title||'Your toolkit')}</h3></span><span class="arrow">↗</span></button>`:''}<div class="notice">Demo suggestions use simple topic and circumstance matching. They are examples to explore, not individualized professional guidance.</div></aside></div>`;
if(page==='circumstances')content=`<div class="content"><button class="back" data-go="today">← Back</button><div class="eyebrow">Make it realistic</div><h1>What works for you right now?</h1><p class="muted">Choose what fits this moment.</p>${[['Setting',['At home','Out and about']],['Your capacity',['Low energy','Ready to join in']],['Time',['5 minutes','10 minutes','20 minutes']],['Materials',['No extra supplies','Basic supplies available']]].map(([label,vals])=>`<section class="section"><h3>${label}</h3><div class="chips">${vals.map(v=>`<button class="chip ${data.filters.includes(v)?'selected':''}" aria-pressed="${data.filters.includes(v)}" data-filter="${v}" data-group="${vals.join('|')}">${v}</button>`).join('')}</div></section>`).join('')}<button class="primary" data-go="today">Use these circumstances <span>→</span></button></div>`;
if(page==='options'){let opts=options(),shown=[opts[offset%opts.length],opts[(offset+1)%opts.length]];content=`<div class="split"><section><button class="back" data-go="today">← Your concern</button><div class="eyebrow">Options for this moment</div><h1>A few ways forward.</h1><p class="muted">${esc(data.concern||activeChild().goals.join(', '))}</p><div class="chips">${data.filters.map(f=>`<span class="chip">${esc(f)}</span>`).join('')}</div>${shown.map((x,i)=>`<button class="row" data-idea="${x.id}"><span class="row-no">0${i+1}</span><span class="grow"><h2>${x.title}</h2><p class="option-desc">${x.desc}</p><div class="meta">${x.time} · ${x.supplies}</div></span><span class="arrow">›</span></button>`).join('')}<div class="actions"><button class="link" id="more">Show other options</button><button class="link" data-go="circumstances">Adjust your circumstances</button></div></section><aside class="panel peach"><div class="small-art">${art()}</div><h2>Try what feels possible.</h2><p class="muted">These are starting points. Adapt them, skip them, or try something else.</p><p class="muted">Sample suggestions for prototype testing.</p></aside></div>`}
if(page==='detail'){let x=selected||ideas[0];selected=x;content=`<div class="split"><section><button class="back" data-go="${lastPage}">← Back</button><div class="eyebrow">One approach to try</div><h1>${x.title}.</h1><p class="muted">${x.time} · ${x.supplies}</p><ol class="steps">${x.steps.map((s,i)=>`<li><span>${i+1}</span>${s}</li>`).join('')}</ol><div class="quote"><span class="badge">Words you could try</span><p>“${x.quote}”</p></div><details><summary>If this doesn't work</summary><p>${x.fallback}</p></details><details><summary>About this suggestion + resources</summary><p>This is illustrative prototype content, not a clinically reviewed recommendation. Adapt it to your child's abilities and supervise as appropriate.</p><button class="link" data-go="resources">Explore resource categories →</button></details><div class="actions"><button class="primary" id="try">I'll try this <span>→</span></button><button class="link" data-save="${x.id}">${data.saved.includes(x.id)?'✓ Saved · Remove':'♡ Save for later'}</button></div></section><aside class="panel lav"><div class="small-art">${art()}</div><h2>Make it your own.</h2><p class="muted">You know your family. A small adjustment can make an option feel more realistic.</p></aside></div>`}
if(page==='feedback')content=`<div class="content feedback-panel"><div class="eyebrow">Room to learn</div><h1>How did it go?</h1><p>${esc((selected||ideas[0]).title)}</p><div class="feedback-choices" role="group" aria-label="Did the suggestion help?">${['Helped','Partly',"Didn't fit"].map(c=>`<button class="${feedbackChoice===c?'selected':''}" data-feedback="${esc(c)}" aria-pressed="${feedbackChoice===c}">${c}</button>`).join('')}</div><label class="field"><span>Anything you'd change? <span class="muted">(optional)</span></span><textarea id="feedback-note" placeholder="A quick note, if you'd like…"></textarea></label><p class="muted">Your response stays in your family’s browser toolkit.</p><div class="actions"><button class="primary" id="save-feedback">Save feedback <span>→</span></button><button class="link" data-go="today">Skip</button></div></div>`;
if(page==='toolkit')content=`<div class="content"><div class="eyebrow">Keep what fits</div><h1>Your family's toolkit.</h1><input class="search" id="toolkit-search" type="search" aria-label="Search toolkit" placeholder="Find an idea or resource" value="${esc(query)}"><div class="tabs"><button class="tab ${tab==='saved'?'active':''}" data-tab="saved">Saved ideas</button><button class="tab ${tab==='history'?'active':''}" data-tab="history">What we tried</button><button class="tab" data-go="resources">Resources ↗</button></div><div id="toolkit-list">${toolkitList()}</div><div class="actions"><button class="link" data-go="today">+ Find another option</button></div></div>`;
if(page==='resources')content=`<div class="content"><button class="back" data-go="toolkit">← Your toolkit</button><div class="eyebrow">Explore at your pace</div><h1>Find what fits.</h1><p class="muted">A small starter collection to explore. These external resources aren't the source of the demo suggestions.</p><input class="search" type="search" id="resource-search" placeholder="Search resources" aria-label="Search resources"><div class="chips">${['All','Parent guidance','Books & learning','Play & outdoors'].map(c=>`<button class="chip ${resourceCategory===c?'selected':''}" data-category="${c}">${c}</button>`).join('')}</div><div id="resource-list">${resourceList()}</div></div>`;
shell(content)}
const resources=[{title:'HealthyChildren.org',category:'Parent guidance',desc:'Parent information from the American Academy of Pediatrics.',url:'https://www.healthychildren.org/'},{title:'ZERO TO THREE',category:'Parent guidance',desc:'Explore resources focused on babies, toddlers, and their caregivers.',url:'https://www.zerotothree.org/'},{title:'Reading Rockets',category:'Books & learning',desc:'Explore reading activities and resources for families.',url:'https://www.readingrockets.org/'},{title:'PBS KIDS for Parents',category:'Play & outdoors',desc:'Browse activities, play ideas, and family resources.',url:'https://www.pbs.org/parents/'},{title:'Your local library',category:'Books & learning',desc:'An idea to explore: check your library for story times, books, and family events.',url:null},{title:'A nearby park',category:'Play & outdoors',desc:'An idea to explore: choose a familiar, accessible outdoor spot for your family.',url:null}];
function resourceList(){let list=resources.filter(r=>(resourceCategory==='All'||r.category===resourceCategory)&&(r.title+' '+r.desc).toLowerCase().includes(query.toLowerCase()));return list.map(r=>`<article class="resource"><div class="category-count">${r.category}</div><h3>${r.title}</h3><p class="muted">${r.desc}</p>${r.url?`<a href="${r.url}" target="_blank" rel="noopener noreferrer">Visit resource ↗</a>`:''}</article>`).join('')||'<p class="empty">No matches. Try another search.</p>'}
function toolkitList(){if(tab==='history')return data.feedback.filter(f=>(ideas.find(x=>x.id===f.id)?.title+' '+f.note).toLowerCase().includes(query.toLowerCase())).slice().reverse().map(f=>`<article class="row"><div class="grow"><h3>${esc(ideas.find(x=>x.id===f.id)?.title)}</h3><span class="meta">${esc(f.result)} · ${new Date(f.date).toLocaleDateString()}</span>${f.note?`<p class="muted">${esc(f.note)}</p>`:''}</div><button class="link" data-idea="${f.id}">Revisit</button></article>`).join('')||'<p class="empty">Your reflections will appear here after you try an idea.</p>';return ideas.filter(x=>data.saved.includes(x.id)&&x.title.toLowerCase().includes(query.toLowerCase())).map(x=>`<div class="row"><button class="grow" style="text-align:left;padding:0" data-idea="${x.id}"><h3>${x.title}</h3><span class="meta">${x.time} · ${x.supplies}</span></button><button class="save-toggle" data-save="${x.id}" aria-label="Remove ${x.title}">Remove</button></div>`).join('')||'<p class="empty">Save an option you like and it will be waiting here.</p>'}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(page==='today'&&$('#concern')){data.concern=$('#concern').value;persist()}navigate(b.dataset.go)});document.querySelectorAll('[data-idea]').forEach(b=>b.onclick=()=>selectIdea(b.dataset.idea,page));document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>saveIdea(b.dataset.save));$('#explore')?.addEventListener('click',()=>{data.started=true;data.concern='My child asks for videos after school. What else could we try?';persist();navigate('today')});$('#family-form')?.addEventListener('submit',e=>{e.preventDefault();familyDraft=collectFamily(new FormData(e.target));const errors=familyErrors(familyDraft);if(errors.length){$('#family-errors').innerHTML=errors.map(e=>'<p>'+esc(e)+'</p>').join('');$('#family-errors').focus();return}data.family=structuredClone(familyDraft);if(!data.family.children.some(c=>c.id===data.family.activeChildId))data.family.activeChildId=data.family.children[0].id;data.started=true;persist();navigate('today');toast('Family unit saved')});
$('#add-child')?.addEventListener('click',()=>{familyDraft=collectFamily(new FormData($('#family-form')));const c=newChild();familyDraft.children.push(c);render();document.querySelector('[name="name-'+c.id+'"]').focus()});
document.querySelectorAll('[data-remove-child]').forEach(b=>b.onclick=()=>{familyDraft=collectFamily(new FormData($('#family-form')));familyDraft.children=familyDraft.children.filter(c=>c.id!==b.dataset.removeChild);render();$('#add-child').focus()});
document.querySelectorAll('[name^="goals-"]').forEach(input=>input.addEventListener('change',()=>{const id=input.name.slice(6);const checked=Array.from(document.querySelectorAll('[name="goals-'+id+'"]:checked')).some(x=>x.value==='Something else');const field=$('#other-field-'+id);field.hidden=!checked;field.querySelector('input').required=checked}));
$('#active-child')?.addEventListener('change',e=>{data.family.activeChildId=e.target.value;persist();toast('Options will use this child’s topics')});
$('#ask-form')?.addEventListener('submit',e=>{e.preventDefault();data.concern=$('#concern').value.trim()||'My child asks for videos after school. What else could we try?';data.started=true;offset=0;persist();navigate('options')});$('.example')?.addEventListener('click',()=>{$('#concern').value='Bedtime is always a struggle';$('#concern').focus()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{let vals=b.dataset.group.split('|');data.filters=data.filters.filter(v=>!vals.includes(v));data.filters.push(b.dataset.filter);persist();render()});$('#more')?.addEventListener('click',()=>{offset=(offset+2)%ideas.length;render()});$('#try')?.addEventListener('click',()=>{feedbackChoice='';navigate('feedback')});document.querySelectorAll('[data-feedback]').forEach(b=>b.onclick=()=>{feedbackChoice=b.dataset.feedback;document.querySelectorAll('[data-feedback]').forEach(x=>{x.classList.toggle('selected',x.dataset.feedback===feedbackChoice);x.setAttribute('aria-pressed',x.dataset.feedback===feedbackChoice)})});$('#save-feedback')?.addEventListener('click',()=>{if(!feedbackChoice){toast('Choose Helped, Partly, or Didn’t fit first.');return}let id=(selected||ideas[0]).id;data.feedback.push({id,result:feedbackChoice,note:$('#feedback-note').value,date:new Date().toISOString()});if(feedbackChoice==='Helped'&&!data.saved.includes(id))data.saved.push(id);persist();tab='history';navigate('toolkit');toast('Reflection saved')});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$('#toolkit-search')?.addEventListener('input',e=>{query=e.target.value;$('#toolkit-list').innerHTML=toolkitList();bindList()});$('#resource-search')?.addEventListener('input',e=>{query=e.target.value;$('#resource-list').innerHTML=resourceList()});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{resourceCategory=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('selected',x===b));$('#resource-list').innerHTML=resourceList()});$('#reset')?.addEventListener('click',()=>{if(confirm('Reset family details, saved ideas, and feedback in this browser?')){data=structuredClone(initial);persist();familyDraft=structuredClone(data.family);navigate('family');toast('Demo reset')}})}
function bindList(){document.querySelectorAll('#toolkit-list [data-idea]').forEach(b=>b.onclick=()=>selectIdea(b.dataset.idea,'toolkit'));document.querySelectorAll('#toolkit-list [data-save]').forEach(b=>b.onclick=()=>saveIdea(b.dataset.save))}
render();
